func DecodeRoleJSON(data []byte) (Role, error) {
	fields, err := strictResourceExact(data)
	if err != nil {
		return Role{}, err
	}
	base, err := checkResourceBase(fields, "Role")
	if err != nil {
		return Role{}, err
	}
	spec, err := strictSpec(fields["spec"], []string{"name", "version", "permissions", "state"}, []string{"name", "version", "permissions", "state"})
	if err != nil {
		return Role{}, err
	}
	name, err := fieldString(spec, "name", "/spec/name")
	if err != nil {
		return Role{}, err
	}
	if _, ok := roleNames[name]; !ok {
		return Role{}, common.ContractError("UNKNOWN_ROLE", "/spec/name")
	}
	version, err := fieldInt(spec, "version", "/spec/version")
	if err != nil || version < 1 {
		return Role{}, common.ContractError("INVALID_ROLE_VERSION", "/spec/version")
	}
	permissions, err := fieldStringArray(spec["permissions"], "/spec/permissions")
	if err != nil || len(permissions) < 1 || len(permissions) > 256 {
		return Role{}, common.ContractError("INVALID_PERMISSIONS", "/spec/permissions")
	}
	seen := map[string]struct{}{}
	for index, permission := range permissions {
		if strings.Contains(permission, "*") {
			return Role{}, common.ContractError("WILDCARD_PERMISSION_FORBIDDEN", "/spec/permissions/"+itoa(index))
		}
		if !permissionPattern.MatchString(permission) || len(permission) < 5 || len(permission) > 128 {
			return Role{}, common.ContractError("INVALID_PERMISSION", "/spec/permissions/"+itoa(index))
		}
		if _, duplicate := seen[permission]; duplicate {
			return Role{}, common.ContractError("DUPLICATE_PERMISSION", "/spec/permissions/"+itoa(index))
		}
		seen[permission] = struct{}{}
	}
	state, err := fieldString(spec, "state", "/spec/state")
	if err != nil || state != "active" && state != "deprecated" && state != "revoked" {
		return Role{}, common.ContractError("INVALID_STATE", "/spec/state")
	}
	return Role{ResourceBase: base, Spec: RoleSpec{Name: name, Version: version, Permissions: permissions, State: state}}, nil
}
