	if err != nil || state != "active" && state != "revoked" {
		return RoleBinding{}, common.ContractError("INVALID_STATE", "/spec/state")
	}
	expires, err := optionalDate(spec, "expiresAt", "/spec/expiresAt")
	if err != nil {
		return RoleBinding{}, err
	}
	if err := checkTenantMetadata(base, tenant); err != nil {
		return RoleBinding{}, err
	}
	return RoleBinding{ResourceBase: base, Spec: RoleBindingSpec{TenantRef: tenant, Subject: subject, RoleName: roleName, RoleVersion: roleVersion, Scope: scope, State: state, ExpiresAt: expires}}, nil
