func optionalDate(fields map[string]json.RawMessage, name, path string) (string, error) {
	if _, ok := fields[name]; !ok {
		return "", nil
	}
	value, err := fieldString(fields, name, path)
	if err != nil {
		return "", err
	}
	if err := common.ValidateDateTime(value, path); err != nil {
		return "", err
	}
	return value, nil
}
func itoa(value int) string {
	if value == 0 {
		return "0"
	}
	result := ""
	for value > 0 {
		result = string(rune('0'+value%10)) + result
		value /= 10
	}
	return result
}
